def _write_body(self, body: bytes) -> None:
    try:
        for offset in range(0, len(body), 64 * 1024):
            self.wfile.write(body[offset : offset + 64 * 1024])
    except (BrokenPipeError, ConnectionResetError):
        self.close_connection = True
